Algorithm Prime
  Define n As Integer;
  Read n;
  Define isPrime As Boolean <- True;
  For d <- 2 To n - 1 Do
    If n Mod d = 0 Then
      isPrime <- False;
      Break;
    EndIf
  EndFor
  If isPrime Then
    Write "Is prime";
  Else
    Write "Not prime";
  EndIf
EndAlgorithm

